mapper.update:
update chat_credit_session
set refund_state = #{toState}, update_time = now()
where user_id = #{userId}
  and request_id = #{requestId}
  and deducted = 1
  and refund_state = #{fromState}

update chat_credit_session
set deduct_state = #{toState},
    deducted = CASE WHEN #{toState} = 'deducted' THEN 1 ELSE deducted END,
    retry_count = CASE WHEN #{toState} IN ('deducted', 'failed') THEN 0 ELSE retry_count END,
    last_error = CASE WHEN #{toState} IN ('deducted', 'failed') THEN null ELSE last_error END,
    next_retry_time = CASE WHEN #{toState} IN ('deducted', 'failed') THEN null ELSE next_retry_time END,
    update_time = now()
where user_id = #{userId}
  and request_id = #{requestId}
  and deduct_state = #{fromState}

update chat_credit_session
set deduct_state = 'deducted', deducted = 1, retry_count = 0,
    last_error = null, next_retry_time = null, update_time = now()
where user_id = #{userId}
  and request_id = #{requestId}
  and deduct_state IN ('deducting', 'deducted')

mapper.select:
select id, user_id, request_id, deducted, deduct_amount, deduct_state, refund_state, retry_count, last_error, next_retry_time
from chat_credit_session
where refund_state = 'pending' and retry_count < #{maxRetry}
  and (next_retry_time is null or next_retry_time <= NOW())
order by coalesce(next_retry_time, create_time), create_time, id
limit #{limit}

select id, user_id, request_id, deducted, deduct_amount, deduct_state, refund_state, retry_count, last_error, next_retry_time
from chat_credit_session
where deduct_state = 'deducting' and retry_count < #{maxRetry}
  and (next_retry_time is null or next_retry_time <= NOW())
order by coalesce(next_retry_time, create_time), create_time, id
limit #{limit}
